import importlib
import json
import os
import sys
import tempfile
import unittest

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), ".."))
sys.path.insert(0, ROOT)

CASES = [["fieldkit.inputs", "m.load_numbers(P['nums'])", ["ok", "[10, 20, 30, 40]"]], ["fieldkit.inputs", "m.count_rows(P['nums'])", ["ok", "3"]], ["fieldkit.inputs", "m.count_rows(P['crlf'])", ["ok", "3"]], ["fieldkit.inputs", "m.read_total(P['nums'])", ["ok", "100"]], ["fieldkit.inputs", "m.words_of(P['words'])", ["ok", "[\"caf\\u00e9\", \"cr\\u00e8me\", \"\\u4e2d\\u6587\", \"plain\"]"]], ["fieldkit.inputs", "m.load_numbers(P['empty'])", ["ok", "[]"]], ["fieldkit.inputs", "m.count_rows(P['empty'])", ["ok", "0"]], ["fieldkit.inputs", "m.load_numbers(P['bad'])", ["raises", "ValueError"]], ["fieldkit.money", "m.ordered([300, -5, 120, 0])", ["ok", "[-5, 0, 120, 300]"]], ["fieldkit.money", "m.ordered([])", ["ok", "[]"]], ["fieldkit.money", "m.nonzero([0, 5, -1])", ["ok", "[false, true, true]"]], ["fieldkit.money", "m.halves([1234, 5, -5, 0, 101])", ["ok", "[\"6.17\", \"0.02\", \"-0.03\", \"0.00\", \"0.50\"]"]], ["fieldkit.money", "m.fmt([1234, 5, -5, 0, 100, -100050])", ["ok", "[\"12.34\", \"0.05\", \"-0.05\", \"0.00\", \"1.00\", \"-1000.50\"]"]], ["fieldkit.money", "m.biggest([5, 900, -3])", ["ok", "900"]]]


def make_files(tmp):
    out = {}
    for name, data in (("nums", b"10 20\n30\n  40 \n"), ("crlf", b"a\r\nb\r\nc"), ("empty", b""), ("bad", b"1 two 3"),
                       ("words", "caf\u00e9 cr\u00e8me  \u4e2d\u6587\nplain".encode("utf-8"))):
        p = os.path.join(tmp, name + ".txt")
        with open(p, "wb") as fh:
            fh.write(data)
        out[name] = p
    return out


def evaluate(modname, expr, P):
    m = importlib.import_module(modname)
    try:
        return ["ok", json.dumps(eval(expr, {"m": m, "P": P}), sort_keys=True)]
    except Exception as ex:
        return ["raises", type(ex).__name__]


class Behaviour(unittest.TestCase):
    def test_calls(self):
        P = make_files(tempfile.mkdtemp())
        bad = []
        for modname, expr, want in CASES:
            got = evaluate(modname, expr, P)
            if got != want:
                bad.append("%s: %s -> %s, want %s" % (modname, expr, got, want))
        self.assertEqual(bad, [], "\n" + "\n".join(bad[:8]))


if __name__ == "__main__":
    unittest.main()

