import io


class Ledger(object):
    def __init__(self):
        self.lots = {}

    def add(self, sku, qty):
        if sku in self.lots:
            self.lots[sku] += qty
        else:
            self.lots[sku] = qty

    def lines(self):
        return ["%s=%d" % (sku, qty) for sku, qty in sorted(self.lots.items())]

    def total(self):
        n = 0
        for qty in self.lots.values():
            n += qty
        return n


