import importlib
import json
import os
import sys
import tempfile
import unittest

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), ".."))
sys.path.insert(0, ROOT)

CASES = [["fieldkit.tagging", "m.tag_of('ab-12 c\\u00e9!')", ["ok", "\"AB12C\""]], ["fieldkit.tagging", "m.tag_of(b'x_y z\\xc3\\xa9 9')", ["ok", "\"XYZ9\""]], ["fieldkit.hashing", "m.digest('hello')", ["ok", "\"5d41402abc4b2a76b9719d911017c592\""]], ["fieldkit.hashing", "m.digest('caf\\u00e9', 'sha1')", ["ok", "\"f424452a9673918c6f09b0cdd35b20be8e6ae7d7\""]], ["fieldkit.reports", "m.prune({'a': 1, 'b': 5, 'c': 3}, 3)", ["ok", "[[\"b\", 5], [\"c\", 3]]"]], ["fieldkit.reports", "m.prune({}, 1)", ["ok", "[]"]], ["fieldkit.compat", "m.encode_query({'q': 'a b', 'z': 'caf\\u00e9/1'})", ["ok", "\"q=a%20b&z=caf%C3%A9/1\""]], ["fieldkit.compat", "m.encode_query({})", ["ok", "\"\""]]]


def make_files(tmp):
    out = {}
    for name, data in (("nums", b"10 20\n30\n  40 \n"), ("crlf", b"a\r\nb\r\nc"), ("empty", b""), ("bad", b"1 two 3"),
                       ("words", "caf\u00e9 cr\u00e8me  \u4e2d\u6587\nplain".encode("utf-8"))):
        p = os.path.join(tmp, name + ".txt")
        with open(p, "wb") as fh:
            fh.write(data)
        out[name] = p
    return out


def evaluate(modname, expr, P):
    m = importlib.import_module(modname)
    try:
        return ["ok", json.dumps(eval(expr, {"m": m, "P": P}), sort_keys=True)]
    except Exception as ex:
        return ["raises", type(ex).__name__]


class SmokeTests(unittest.TestCase):
    def test_sample_calls(self):
        P = make_files(tempfile.mkdtemp())
        for modname, expr, want in CASES:
            self.assertEqual(evaluate(modname, expr, P), want, "%s: %s" % (modname, expr))


if __name__ == "__main__":
    unittest.main()

