"""Stock ledger for a seed library."""
import io


class Ledger(object):
    def __init__(self):
        self.lots = {}

    def add(self, sku, qty):
        if sku in self.lots:
            self.lots[sku] += qty
        else:
            self.lots[sku] = qty

    def lines(self):
        return ["%s=%d" % (sku, qty) for sku, qty in sorted(self.lots.items())]

    def total(self):
        n = 0
        for qty in self.lots.values():
            n += qty
        return n


def _fill(pairs):
    ledger = Ledger()
    for sku, qty in pairs:
        ledger.add(sku, qty)
    return ledger


def ledger_lines(pairs):
    return _fill(pairs).lines()


def ledger_total(pairs):
    return _fill(pairs).total()


def ledger_dump(pairs):
    out = io.StringIO()
    ledger = _fill(pairs)
    for line in ledger.lines():
        print(line, file=out)
    print("total:", ledger.total(), end="", file=out)
    return out.getvalue()


def spread(n):
    return [i * 3 for i in range(n)]

